def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr = min(y for y, x in cells)
            minc = min(x for y, x in cells)
            shape = frozenset((y - minr, x - minc) for y, x in cells)
            comps.append((color, cells, shape))

    # Find matching nontrivial shapes; repaint the matching object to color 5.
    candidates = []
    for i, a in enumerate(comps):
        if len(a[1]) < 2:
            continue
        for b in comps[i + 1:]:
            if a[2] == b[2] and a[0] != b[0]:
                if a[0] == 5:
                    candidates.append((b, a))
                elif b[0] == 5:
                    candidates.append((a, b))
                else:
                    # In the demonstrated pattern, color 1 is the object repainted.
                    target = a if a[0] == 1 else b if b[0] == 1 else a
                    candidates.append((target, None))

    out = [row[:] for row in grid]
    if candidates:
        target = candidates[0][0]
        for r, c in target[1]:
            out[r][c] = 5
    return out
